// What the site loader does on each Squarespace page. The selectors and paths below are
// production's, found by trial and error against Squarespace's markup: do not "improve" them.

import { fetchCampaign } from './api';
import type { RgCampaignDetail } from './campaign-detail';
import { ensurePageStyles } from './page-styles';
import { detailSlug, isListingPath } from '../routes';

/** Marks what we inserted, so a Squarespace page change can clear it before re-mounting. */
const MARK = 'data-rgai-page';

function clearInserted(): void {
  document.querySelectorAll(`[${MARK}]`).forEach((el) => el.remove());
}

// `.product-content-wrapper` is hidden by CSS; our content goes next to it, in the same spot in the
// page flow, without depending on any of Squarespace's markup inside it.
function insertAfterContentWrapper(el: HTMLElement): void {
  el.setAttribute(MARK, '');
  const wrapper = document.querySelector('.product-content-wrapper');
  if (wrapper) {
    wrapper.insertAdjacentElement('afterend', el);
    return;
  }
  const detail = document.querySelector('.product-detail');
  if (detail) {
    detail.appendChild(el);
    return;
  }
  console.error('campaign detail page: no anchor found — nothing inserted to avoid clobbering the page.');
}

async function mountDetail(slug: string): Promise<void> {
  // Read the image Squarespace rendered natively before it is hidden: the fallback for a campaign
  // that has none of its own (for example a test product whose image was uploaded in Squarespace).
  const nativeImg = document.querySelector<HTMLImageElement>('.product-gallery-slides-item-image');
  const el = document.createElement('rg-campaign-detail') as RgCampaignDetail;
  el.fallbackImageUrl = (nativeImg && (nativeImg.currentSrc || nativeImg.src)) || '';
  try {
    const campaign = await fetchCampaign(slug);
    if (campaign) el.campaign = campaign;
    else el.notFound = true;
  } catch (err) {
    console.error('Failed to load campaign:', err);
    el.notFound = true;
  }
  insertAfterContentWrapper(el);
}

function mountListing(): void {
  const container = document.querySelector('.product-list-container');
  if (!container) {
    console.error('campaign grid: .product-list-container not found — nothing inserted.');
    return;
  }
  const el = document.createElement('rg-campaign-listing');
  el.setAttribute(MARK, '');
  container.insertAdjacentElement('afterend', el);
}

/** Run on first load and again on every Squarespace page change (`mercury:load`). */
export function mountCampaignPages(pathname: string = window.location.pathname): void {
  clearInserted();
  const slug = detailSlug(pathname);
  if (slug) {
    ensurePageStyles();
    void mountDetail(slug);
  } else if (isListingPath(pathname)) {
    ensurePageStyles();
    mountListing();
  }
}
