import { hideNativeStyles } from './styles/hide';

const STYLE_ID = 'rgai-page-styles';

/**
 * The few rules that must live in the page itself, not in a Shadow DOM:
 *  - hide Squarespace's native product UI that our elements replace (selectors as in production);
 *  - lay our listing element out inside Squarespace's content track (production's `.cg-intro,
 *    .cg-grid` rule, applied to the host).
 * The brand font is declared by <rg-bulb> itself (bulb/brand-font.ts), on whatever page it is.
 */
export function pageStyles(): string {
  return `${hideNativeStyles}
rg-campaign-detail { display: block; }
rg-campaign-listing {
  display: block;
  contain: inline-size;
  min-width: 0;
  box-sizing: border-box;
  width: 100% !important;
  max-width: min(var(--container-width, 1200px), 100%);
  flex: 1 1 100% !important;
  grid-column: 1 / -1 !important;
  margin-left: auto;
  margin-right: auto;
}`;
}

/** Adds the page-level styles once (safe to call again on a Squarespace page change). */
export function ensurePageStyles(): void {
  if (document.getElementById(STYLE_ID)) return;
  const style = document.createElement('style');
  style.id = STYLE_ID;
  style.textContent = pageStyles();
  document.head.appendChild(style);
}
